    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    // Store gem positions
    vector<pair<int, int>> gems(n);
    for (int i = 0; i < n; i++) {
        cin >> gems[i].first >> gems[i].second;
    }

    int m;
    cin >> m;

    // Current position starts at (10, 10)
    int x = 10, y = 10;

    // Simulate movements and check gems
    for (int i = 0; i < m; i++) {
        char dir;
        int steps;
        cin >> dir >> steps;

        // Move step by step
        for (int s = 0; s < steps; s++) {
            // Update position based on direction
            if (dir == 'U') y++;
            else if (dir == 'D') y--;
            else if (dir == 'L') x--;
            else if (dir == 'R') x++;

            // Check bounds (should stay within 0-20)
