using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    set<pair<int,int>> gems;
    for (int i = 0; i < n; ++i) {
        int x, y;
        cin >> x >> y;
        gems.insert({x, y});
    }

    int x = 10, y = 10;
    if (gems.count({x, y})) gems.erase({x, y});

    for (int i = 0; i < m; ++i) {
        char c;
        int d;
        cin >> c >> d;

        int nx = x, ny = y;
        if (c == 'U') ny += d;
        else if (c == 'D') ny -= d;
        else if (c == 'L') nx -= d;
        else if (c == 'R') nx += d;

        // Collect gems on every integer point along the path, including endpoint.
        if (x == nx) {
            int lo = min(y, ny), hi = max(y, ny);
            for (auto it = gems.begin(); it != gems.end(); ) {
                if (it->first == x && it->second >= lo && it->second <= hi)
                    it = gems.erase(it);
                else
                    ++it;
            }
        } else {
            int lo = min(x, nx), hi = max(x, nx);
            for (auto it = gems.begin(); it != gems.end(); ) {
                if (it->second == y && it->first >= lo && it->first <= hi)
                    it = gems.erase(it);
                else
                    ++it;
            }
        }

        x = nx;
        y = ny;
    }

    cout << (gems.empty() ? "Yes" : "No") << '\n';
    return 0;
}

#include <stdio.h>
