#include <math.h>

int main() {
    int n;
    scanf("%d", &n);

    // Store gem positions
    double gems_x[100], gems_y[100];
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &gems_x[i], &gems_y[i]);
    }

    int m;
    scanf("%d", &m);

    // Starting position
    double x = 10.0, y = 10.0;
    int collected[100] = {0};
    int collected_count = 0;

    // Check if starting position has a gem
    for (int i = 0; i < n; i++) {
        if (fabs(x - gems_x[i]) < 1e-9 && fabs(y - gems_y[i]) < 1e-9) {
            if (!collected[i]) {
                collected[i] = 1;
                collected_count++;
            }
        }
    }

    // Process commands
    for (int i = 0; i < m; i++) {
        char direction[10];
        double distance;
        scanf("%s %lf", direction, &distance);

        // Move robot
        if (strcmp(direction, "UP") == 0) {
            y += distance;
        } else if (strcmp(direction, "DOWN") == 0) {
            y -= distance;
        } else if (strcmp(direction, "LEFT") == 0) {
            x -= distance;
        } else if (strcmp(direction, "RIGHT") == 0) {
            x += distance;
        }

        // Check boundaries (0 to 20)
        if (x < 0 || x > 20 || y < 0 || y > 20) {
            printf("NO\n");
            return 0;
        }

        // Check if current position has any uncollected gem
        for (int j = 0; j < n; j++) {
            if (!collected[j] && fabs(x - gems_x[j]) < 1e-9 && fabs(y - gems_y[j]) < 1e-9) {
                collected[j] = 1;
                collected_count++;
            }
        }
    }

    // Check if all gems collected
    if (collected_count == n) {
        printf("YES\n");
    } else {
        printf("NO\n");
    }

    return 0;
}

