#define EPS 1e-9

typedef struct {
    double x, y;
} Point;

static double dist2(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return dx * dx + dy * dy;
}

int main(void) {
    int n, m;

    /* 
       Assumed input format:
       n m
       x1 y1
       ...
       xn yn
       dx1 dy1
       ...
       dxm dym

       - n: number of gems
       - m: number of movement commands
       - robot starts at (10,10)
       - each command moves robot by vector (dx,dy)
       - a gem is collected if robot ever stands exactly on its position
       - robot must always remain inside [0,20] x [0,20]
       Output:
       YES if all gems can be collected after executing all commands, otherwise NO
    */

    if (scanf("%d %d", &n, &m) != 2) return 0;

    Point *gems = (Point *)malloc(sizeof(Point) * n);
    int *collected = (int *)calloc(n, sizeof(int));
    if (!gems || !collected) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &gems[i].x, &gems[i].y);
    }

    Point cur = {10.0, 10.0};

    for (int i = 0; i < n; i++) {
        if (dist2(cur, gems[i]) < EPS) collected[i] = 1;
    }

    for (int i = 0; i < m; i++) {
        double dx, dy;
        scanf("%lf %lf", &dx, &dy);

        cur.x += dx;
        cur.y += dy;

        if (cur.x < -EPS || cur.x > 20.0 + EPS || cur.y < -EPS || cur.y > 20.0 + EPS) {
            printf("NO\n");
            free(gems);
            free(collected);
            return 0;
        }

        for (int j = 0; j < n; j++) {
            if (!collected[j] && dist2(cur, gems[j]) < EPS) {
                collected[j] = 1;
            }
        }
    }

    for (int i = 0; i < n; i++) {
        if (!collected[i]) {
            printf("NO\n");
            free(gems);
            free(collected);
            return 0;
        }
    }

    printf("YES\n");

    free(gems);
    free(collected);
    return 0;
}

