import java.io.*;
import java.util.*;

public class GemCollector {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        // Read number of gems
        line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) return;

        int N = Integer.parseInt(line.trim());
        int[][] gems = new int[N][2];

        for (int i = 0; i < N; i++) {
            line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            String[] parts = line.trim().split("\\s+");
            gems[i][0] = Integer.parseInt(parts[0]);
            gems[i][1] = Integer.parseInt(parts[1]);
        }

        // Read number of commands
        line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) return;

        int M = Integer.parseInt(line.trim());
        String[] commands = new String[M];

        for (int i = 0; i < M; i++) {
            line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            commands[i] = line.trim();
        }

        // Simulate robot movement
        int x = 10, y = 10;
        boolean[][] collected = new boolean[21][21];

        // Mark gems that are at start position
        for (int[] gem : gems) {
            if (gem[0] == x && gem[1] == y) {
                collected[gem[0]][gem[1]] = true;
            }
        }

        for (String cmd : commands) {
            switch (cmd) {
                case "UP":
                    y = Math.min(y + 1, 20);
                    break;
                case "DOWN":
                    y = Math.max(y - 1, 0);
                    break;
                case "LEFT":
                    x = Math.max(x - 1, 0);
                    break;
                case "RIGHT":
                    x = Math.min(x + 1, 20);
                    break;
            }

            // Check if current position has a gem
            for (int[] gem : gems) {
                if (gem[0] == x && gem[1] == y) {
                    collected[gem[0]][gem[1]] = true;
                }
            }
        }

        // Check if all gems were collected
        boolean allCollected = true;
        for (int[] gem : gems) {
            if (!collected[gem[0]][gem[1]]) {
                allCollected = false;
                break;
            }
        }

        System.out.println(allCollected ? "YES" : "NO");
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        Set<String> gems = new HashSet<>();
        for (int i = 0; i < n; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            gems.add(x + "," + y);
        }

        int m = sc.nextInt();
        double cx = 10, cy = 10;
        Set<String> collected = new HashSet<>();

        // Check starting position
        String startKey = (int)cx + "," + (int)cy;
        if (gems.contains(startKey)) collected.add(startKey);

        for (int i = 0; i < m; i++) {
            String dir = sc.next();
            int dist = sc.nextInt();

            int dx = 0, dy = 0;
            switch(dir) {
                case "U": dy = 1; break;
                case "D": dy = -1; break;
                case "L": dx = -1; break;
                case "R": dx = 1; break;
            }

            for (int step = 1; step <= dist; step++) {
                cx += dx;
                cy += dy;
                String key = (int)cx + "," + (int)cy;
                if (gems.contains(key)) collected.add(key);
            }
        }

        if (collected.size() == gems.size()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        String first = fs.next();
        if (first == null) return;

        int n = Integer.parseInt(first);

        boolean[][] gem = new boolean[21][21];
        int total = 0;

        for (int i = 0; i < n; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            if (0 <= x && x <= 20 && 0 <= y && y <= 20 && !gem[x][y]) {
                gem[x][y] = true;
                total++;
            }
        }

        String commands = fs.next();
        if (commands == null) commands = "";

        int x = 10, y = 10;
        int collected = 0;

        if (gem[x][y]) {
            gem[x][y] = false;
            collected++;
        }

        for (int i = 0; i < commands.length(); i++) {
            char c = commands.charAt(i);
            int nx = x, ny = y;

            if (c == 'U') ny++;
            else if (c == 'D') ny--;
            else if (c == 'L') nx--;
            else if (c == 'R') nx++;

            if (0 <= nx && nx <= 20 && 0 <= ny && ny <= 20) {
                x = nx;
                y = ny;
                if (gem[x][y]) {
                    gem[x][y] = false;
                    collected++;
                }
            }
        }

        System.out.println(collected == total ? "Yes" : "No");
    }
}
